import {readBoard,writeBoard,RevisionConflict} from './cloud-store.mjs';
const ui=id=>document.getElementById(id),app=window.homeWatch,config=window.HOME_WATCH_CONFIG||{};
let client,user,revision=null,dirty=false,busy=false,blocked=false,timer,generation=0;
const localStateKey=id=>'home-watch-sync-state-'+id;
function state(text,sub){ui('syncstatus').textContent=text;ui('syncsub').textContent=sub||''}
function persist(){if(user)localStorage.setItem(localStateKey(user.id),JSON.stringify({revision,dirty}))}
function editing(on){for(const id of ['add','import'])ui(id).disabled=!on;if(!on){ui('detail').close();ui('editor').close()}}
function statusError(e){state(e instanceof RevisionConflict?'다른 기기의 새 기록이 있어요':'동기화 보류',e instanceof RevisionConflict?e.message:'이 기기의 변경은 보관돼 있어요. 연결을 확인하고 다시 동기화하세요.');if(e instanceof RevisionConflict)blocked=true;console.warn('Cloud sync:',e.message)}
async function push(){if(!user||busy||blocked||!dirty)return;busy=true;const gen=generation,uid=user.id,snapshot=app.getData();state('기록 저장 중','다른 기기에서도 이어 볼 수 있도록 저장하고 있어요.');try{const next=await writeBoard(client,uid,snapshot,revision);if(gen!==generation)return;revision=next;dirty=JSON.stringify(app.getData())!==JSON.stringify(snapshot);persist();state(dirty?'추가 변경 저장 중':'동기화 완료','같은 이메일로 로그인하면 다른 기기에서도 볼 수 있어요.')}catch(e){if(gen===generation)statusError(e)}finally{busy=false} }
// Debounced, serialized saves; new changes during a write are handled by the next pass.
async function flush(){await push();if(dirty&&!blocked&&user&&ui('syncstatus').textContent==='추가 변경 저장 중')await flush()}
window.homeCloud={changed(){if(!user)return;dirty=true;persist();state('이 기기에 변경 저장됨',blocked?'백업 후 최신 기록을 불러와 충돌을 해결하세요.':'계정에 동기화하고 있어요.');clearTimeout(timer);timer=setTimeout(flush,650)}};
async function loadCloud(discard=false){if(!user||busy)return;if(dirty&&!discard){state('동기화할 변경이 있어요','먼저 기기 간 동기화 버튼으로 저장하세요.');return}busy=true;editing(false);const gen=generation,uid=user.id;try{const row=await readBoard(client,uid);if(gen!==generation)return;if(row){if(!app.isValid(row.items))throw Error('Invalid cloud data');app.replaceData(row.items);revision=row.revision;dirty=false;blocked=false;persist();state('동기화 완료','계정의 최신 기록을 불러왔어요.')}else{revision=null;dirty=true;blocked=false;persist();state('첫 동기화 준비됨','기기 간 동기화를 눌러 현재 목록을 계정에 저장하세요.')}}catch(e){if(gen===generation){blocked=true;statusError(e)}}finally{busy=false;editing(true)}}
async function activate(session){const next=session?.user;if(next?.id===user?.id)return;const guest=!user?app.getData():null;const hasCache=next&&localStorage.getItem('hyokyung-home-watch-user-'+next.id)!==null;generation++;clearTimeout(timer);user=next;revision=null;dirty=false;blocked=false;editing(false);app.switchUser(user?.id);if(user&&!hasCache&&guest)app.replaceData(guest);ui('logout').hidden=!user;ui('refreshcloud').hidden=!user;ui('cloudopen').textContent=user?'기기 간 동기화':'기기 간 동기화';if(!user){state('이 브라우저에 저장 중','로그인하면 다른 기기에서도 이어 볼 수 있어요.');editing(true);return}let cache;try{cache=JSON.parse(localStorage.getItem(localStateKey(user.id)))}catch{};revision=cache?.revision??null;dirty=cache?.dirty===true;ui('cloudlogin').close();if(dirty){editing(true);state('저장 대기 중인 변경이 있어요','기기 간 동기화를 눌러 계정에 저장하세요.');return}busy=false;await loadCloud()}
ui('closecloud').onclick=()=>ui('cloudlogin').close();ui('cloudlogin').addEventListener('click',e=>{if(e.target===ui('cloudlogin'))ui('cloudlogin').close()});
ui('cloudopen').onclick=async()=>{if(user){if(blocked){app.notify('백업을 내보낸 뒤 최신 기록 불러오기로 확인하세요.');return}if(dirty){await flush()}else await loadCloud();return}ui('cloudlogin').showModal()};
ui('refreshcloud').onclick=async()=>{if(busy)return;if(dirty&&!confirm('이 기기의 미전송 변경을 계정의 최신 기록으로 교체할까요? 필요하면 먼저 백업을 내보내세요.'))return;await loadCloud(true)};
ui('logout').onclick=async()=>{if(busy){app.notify('저장이 끝난 후 로그아웃하세요.');return}if(dirty&&!confirm('동기화하지 않은 변경은 이 기기에 보관됩니다. 로그아웃할까요?'))return;const {error}=await client.auth.signOut();if(error){app.notify('로그아웃하지 못했어요. 다시 시도하세요.');return}await activate(null)};
ui('loginform').onsubmit=async e=>{e.preventDefault();ui('sendlink').disabled=true;try{const redirect=new URL('.',location.href).href;const {error}=await client.auth.signInWithOtp({email:ui('email').value,options:{emailRedirectTo:redirect}});if(error)throw error;ui('loginmessage').textContent='이메일의 로그인 링크를 이 기기에서 열어주세요.'}catch{ui('loginmessage').textContent='로그인 메일을 보내지 못했어요. 이메일과 연결 설정을 확인하세요.'}finally{ui('sendlink').disabled=false}};
window.addEventListener('online',()=>{if(user&&!blocked)flush()});window.addEventListener('focus',()=>{if(user&&!dirty&&!busy)loadCloud()});
async function init(){if(config.enableCloudSync!==true||!config.supabaseUrl||!config.supabasePublishableKey){ui('loginform').hidden=true;ui('cloudhelp').textContent='기기 간 동기화는 계정 연결을 준비 중이에요. 지금은 이 브라우저에서 기록하고 백업할 수 있어요.';return}try{document.querySelector('.syncbar').hidden=false;const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.49.8');client=createClient(config.supabaseUrl,config.supabasePublishableKey);client.auth.onAuthStateChange((_event,session)=>setTimeout(()=>activate(session),0));const {data,error}=await client.auth.getSession();if(error)throw error;await activate(data.session)}catch(e){ui('loginform').hidden=true;ui('cloudhelp').textContent='로그인 연결을 불러오지 못했어요. 잠시 후 새로고침해 주세요.';state('이 브라우저에 저장 중','계정 연결을 사용할 수 없어 동기화가 보류됐어요.')}}
init();
